query:
-- Squads existentes
SELECT id, teamName, userId FROM squads;

-- Verificar se há jogadores com club = teamName de algum squad
SELECT t.name as teamName, COUNT(p.id) as playerCount
FROM teams t
LEFT JOIN players p ON LOWER(p.club) = LOWER(t.name)
WHERE t.id IN (SELECT DISTINCT teamId FROM squads)
GROUP BY t.id, t.name;

-- Ver exemplos de nomes de clube nos jogadores vs times
SELECT DISTINCT p.club FROM players LIMIT 10;
SELECT name FROM teams LIMIT 10;

